				select data as id into #id from dbo.ISWIFTFunction$Split(@id_m72, ',')
				select @@fields into #t from f72 a @@join
				  where a.id in (select id from #id)
				  order by a.line, a.id

				select id_pn, line_pn, sum(a.sox_luong) as sl_phieu_nhap into #sl from f54 a with(index(id_pn)) where id <> @id and id_pn <> 0 and exists(select 1 from #t b where a.id_pn = b.id_pn and a.line_pn = b.line_pn) group by id_pn, line_pn
				update #t set sl_cl = a.sox_luong - isnull(b.sl_phieu_nhap, 0) from #t a left join #sl b on a.id_pn = b.id_pn and a.line_pn = b.line_pn
				update #t set so_luong0 = sl_cl
				select * from #t where sl_cl <> 0

				select 1 from m72 a where a.id in (select top 1 id from #id order by id desc)

				drop table #id
				drop table #t
				drop table #sl

