function filter$m54PN1Select(p){
  this.constructor(p);
}
filter$m54PN1Select.prototype = new DirEvent();
filter$m54PN1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$m54PN1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id_dh', 'ma_job', 'so_job_dh'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._id_dh,p.options._ma_job, p.options._so_job_dh]);
	dir$m54PN1SetMaster(p);

}

function dir$m54PN1SetMaster(p) {
  //p.request('ma_kh_request', '', ['id']);
}

filter$m54PN1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	dt.removeRow('[so_luong0] == 0');
    pa.appendGrid(1, dt, p.valForm('xprocess') == "2", 'sox_luong', 'so_luong0');
	pa.calcExpressionAll(1, 'sox_luong');
    //pa.appendForm(master, 1);
    p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();


  //p._close();

  return false;
}









			  		DECLARE @ds_cong VARCHAR(4000)  
					SELECT distinct ma_cong into #tt FROM v61 a where a.id = @id
					SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt

					select top 1 a.ma_kh as [!ma_kh],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den], 
					@ds_cong as [!ds_cong],b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den],d.ten_kh as [!ten_kh],e.ten_hang as [!ten_hang], a.dien_giai as [!dien_giai]
				  from s61 a 
				  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
				  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
				  left join dmkh d on a.ma_kh =d.ma_kh 
				  left join vdmhangtau e on a.ma_hang =e.ma_hang 
				  where a.id = @id
